public int findLargestSubstring(List<String> strings) {

    // Edge case: If there are no strings, return 0
    if (strings.isEmpty()) {
        return 0;
    }

    // Initialize variables
    int largestSubstring = 0;
    Set<String> allSubstrings = new HashSet<>();

    // Loop through each string
    for (String string : strings) {
        // Loop through each substring of the current string
        for (int i = 0; i < string.length(); i++) {
            // Check if the substring is in the set
            if (allSubstrings.contains(string.substring(i)) {
                // If it is, update the largest substring
                largestSubstring = Math.max(largestSubstring, string.substring(i).length());
                break;
            } else {
                // If not, add the inverse of the substring to the set
                allSubstrings.add(new StringBuffer(string.substring(i)).reverse().toString());
            }
        }
    }

    return largestSubstring;
}

