public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a Boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n];

    // Initialize the queue for Breadth-First Search (BFS)
    Queue<Integer> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]] = true;
    queue.add(start[0]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection in the queue
        int current = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (current == end[0]) {
            // If it is, return "can be travelled"
            return "can be travelled";
        }

        // Loop through all the paths that originate from the current n-tersection
        for (int i = 0; i < paths.length; i++) {
            // Check if the current path is not valid
            if (!visited[paths[i][0]] && !visited[paths[i][1]]) {
                continue;
            }

            // Mark the destination n-tersection as visited and add it to the queue
            visited[paths[i][1]] = true;
            queue.add(paths[i][1]);
        }
    }

    // If we reach this point, it means that no path from the starting n-tersection leads to the ending n-tersection
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a boolean array to keep track of visited nodes
    boolean[] visited = new boolean[n];
    // Mark the starting node as visited
    visited[start[0]] = true;
    // Initialize a queue for BFS
    Queue<int[]> queue = new LinkedList<>();
    // Add the starting node to the queue
    queue.add(start);
    // loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node from the queue
        int[] current = queue.poll();
        // If the current node is the ending node, return "can be travelled"
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }
        // Loop through all the neighbors of the current node
        for (int i = 0; i < paths.length; i++) {
            // If the neighbor has not been visited and there is a path between the current node and the neighbor
            if (!visited[paths[current[0]][i]] && paths[current[0]][i] != -1) {
                // Mark the neighbor as visited
                visited[paths[current[0]][i]] = true;
                // Add the neighbor to the queue
                queue.add(new int[]{paths[current[0]][i], current[1]});
            }
        }
    }
    // If the queue is empty and the ending node has not been reached, return "cannot be travelled"
    return "cannot be travelled";
}

