    if (n % 2 != 0) {
        return false;
    }
    Map<Integer, Integer> map = new HashMap<>();
    for (int element : arr) {
        if (!map.containsKey(element)) {
            map.put(element, 1);
        } else {
            map.put(element, map.get(element) + 1);
        }
    }
    for (int i = 1; i <= n / 2; i++) {
        int complement = k - i;
