    }
    for (int[] edge : edges) {
        graph[edge[0]].add(edge[1]);
        graph[edge[1]].add(edge[0]);
    }

    // Initialize the minimum time required to collect all apples and return to node 0
    int minTime = 0;

    // Perform a depth-first search to find the shortest path to collect all apples
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(0);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        for (int neighbor : graph[node]) {
            if (!hasApple[neighbor]) {
                continue;
            }
            int neighborTime = Math.max(hasApple[neighbor] ? 2 : 0, minTime + 1);
            minTime = Math.min(minTime, neighborTime);
            queue.offer(neighbor);
        }
    }

    return minTime;
}

public String sortString(String s) {
    // Sort the characters in the string
    char[] chars = s.toCharArray();
    Arrays.sort(chars);

    // Re-order the characters according to the algorithm
    StringBuilder result = new StringBuilder();
    boolean isAscending = true;
    for (int i = 0; i < chars.length; i++) {
        if (i > 0 && chars[i] == chars[i - 1]) {
            // If the current character is the same as the previous one
            continue;
        }
        if (isAscending) {
            // If the current character is ascending
            result.append(chars[i]);
        } else {
            // If the current character is descending
            result.insert(0, chars[i]);
        }
        isAscending = !isAscending;
    }

    return result.toString();
}

public String sortString(String s) {
    char[] array = s.toCharArray();
    Arrays.sort(array);
    StringBuilder result = new StringBuilder();
    while (!array.isEmpty()) {
        char smallest = array[0];
        result.append(smallest);
        array = Arrays.stream(array).filter(c -> c != smallest).toArray(char[]::new);
        if (array.length == 0) {
            break;
        }
        char largest = array[array.length - 1];
        result.append(largest);
        array = Arrays.stream(array).filter(c -> c != largest).toArray(char[]::new);
    }
    return result.toString();
}

public String sortString(String s) {
  if (s.isEmpty()) {
    return s;
  }

  char[] chars = s.toCharArray();
  int n = chars.length;
  int left = 0;
  int right = n - 1;
  StringBuilder result = new StringBuilder();

  while (left < right) {
    result.append(findSmallest(chars, left, right));
    left++;
    result.append(findLargest(chars, left, right));
    right--;
  }

  if (left == right) {
    result.append((char) chars[left]);
  }

  return result.toString();
}

public String sortString(String s) {
    // Step 1: Pick the smallest character from s and append it to the result.
    String result = s.substring(0, 1);
    s = s.substring(1);
    while (s.length() > 0) {
        // Step 2: Pick the smallest character from s which is greater than the last appended character to the result and append it.
        char lastChar = result.charAt(result.length() - 1);
        int minIndex = -1;
        char minChar = Character.MAX_VALUE;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) > lastChar && s.charAt(i) < minChar) {
                minIndex = i;
                minChar = s.charAt(i);
            }
        }
        result += minChar;
        s = s.substring(0, minIndex) + s.substring(minIndex + 1);
        // Step 3: Repeat step 2 until you cannot pick more characters.
        if (s.length() == 0) {
            break;
        }
        // Step 4: Pick the largest character from s and append it to the result.
        lastChar = result.charAt(result.length() - 1);
        int maxIndex = -1;
        char maxChar = Character.MIN_VALUE;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < lastChar && s.charAt(i) > maxChar) {
                maxIndex = i;
                maxChar = s.charAt(i);
            }
        }
        result += maxChar;
        s = s.substring(0, maxIndex) + s.substring(maxIndex + 1);
        // Step 5: Pick the largest character from s which is smaller than the last appended character to the result and append it.
        while (s.length() > 0) {
            lastChar = result.charAt(result.length() - 1);
            minIndex = -1;
            minChar = Character.MAX_VALUE;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) < lastChar && s.charAt(i) > minChar) {
                    minIndex = i;
                    minChar = s.charAt(i);
                }
            }
            if (minIndex == -1) {
                break;
            }
            result += minChar;
            s = s.substring(0, minIndex) + s.substring(minIndex + 1);
            // Step 6: Repeat step 5 until you cannot pick more characters.
            if (s.length() == 0) {
                break;
            }
        }
    }
    return result;
}

public String sortString(String s) {
    if (s.length() == 0) {
        return "";
    }
    String sorted = "";
    while (sorted.length() < s.length()) {
        int minIndex = 0;
        int maxIndex = s.length() - 1;
        for (int i = 1; i < s.length(); i++) {
            if (s.charAt(i) < s.charAt(minIndex)) {
                minIndex = i;
            }
            if (s.charAt(i) > s.charAt(maxIndex)) {
                maxIndex = i;
            }
        }
        sorted += s.charAt(minIndex);
        sorted += s.charAt(maxIndex);
        s = s.replace(s.charAt(minIndex), ' ');
        s = s.replace(s.charAt(maxIndex), ' ');
    }
    return sorted;
}

