public static double calculateProbability(int n) {
    // Initialize probability to 1.0
    double probability = 1.0;

    // Iterate from 1 to n - 1
    for (int i = 1; i < n; i++) {
        // Calculate the probability that the last passenger will sit in their own seat
        probability *= 1 - (1.0 / (n - i + 1));
    }

    return probability;
}

