public static int singleNumber(int[] nums) {

/**
 * There are a few ways to approach this problem, but one approach is to use a hash table to count the frequency of each number in the array. Since every element appears three times except for one, the unique element will have a frequency of 1, while all the other elements will have a frequency of 3.
 *
 * So, we can iterate through the array, using a HashMap to keep track of the frequency of each element. At the end of the iteration, we can then iterate through the HashMap to find the key (element in the array) with a value of 1, which will be the unique element.
 *
 * Alternatively, we can use the bitwise XOR operator (`^`) to solve this problem. The XOR operator has the property that `a ^ a = 0`, and `a ^ 0 = a`, so when we XOR all the elements in the array together, the unique element will be the one that doesn't disappear.
 *
 * Here's an example of how this approach would work:
 *
 * nums = [2, 2, 3, 2]
 *
 * 2 ^ 2 ^ 3 ^ 2 = 3
 *
 * So, 3 is the unique element in the array.
 */

// HashMap approach
HashMap<Integer, Integer> count = new HashMap<Integer, Integer>();
for (int i : nums) {
count.put(i, count.getOrDefault(i, 0) + 1);
}

for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
if (entry.getValue() == 1) {
return entry.getKey();
}
}

// XOR approach
int result = 0;
for (int i : nums) {
result ^= i;
}

return result;
}

public static int singleNumber(int[] nums) {
    Map<Integer, Integer> count = new HashMap<>();
    for (int num : nums) {
        count.put(num, count.getOrDefault(num, 0) + 1);
    }
    for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
        if (entry.getValue() == 1) {
            return entry.getKey();
        }
    }
    return -1;
}

public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0, threes = 0;
    for (int num : nums) {
        ones = (ones ^ num) & ~twos;
        twos = (twos ^ num) & ~ones;
        threes = (threes ^ num) & ~ones & ~twos;
    }
    return ones;
}

