public static int countDigitOne(int n) {
    // For each digit in the number, calculate the number of times the digit 1 appears in all numbers with that digit as the most significant digit.
    // Then, calculate the number of times the digit 1 appears in all numbers with that digit as the second most significant digit, etc.
    // Finally, sum up the results.
    int count = 0;
    for (int i = 1; i <= n; i *= 10) {
        // Sum up the count for each digit.
        count += i / 10 * (n / i);
        // Add the count for the numbers with a digit 1 as the most significant digit in for the current significant digit.
        count += n % i / (i / 10);
    }
    return count;
}

