    int count = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            permutations[i] = A[i] + A[j];
            if (isPerfectSquare(permutations[i])) {
                permutations[j] = permutations[i];
                count++;
            }
        }
    }
