}

public static int squarePermutations(int[] A) {
    // Initialize a boolean array to keep track of the pairs that form a perfect square
    boolean[] isSquare = new boolean[A.length];
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        int squareRoot = (int) Math.sqrt(sum);
        if (squareRoot * squareRoot == sum) {
            isSquare[i] = true;
            isSquare[i + 1] = true;
        }
    }

    // Count the number of permutations
    int count = 0;
    for (int i = 0; i < isSquare.length; i++) {
        if (isSquare[i]) {
            count++;
        }
    }

    return count;
}

