        for (int j = i + 1; j < A.length; j++) {
            int sum = A[i] + A[j];
            int root = (int) Math.sqrt(sum);
            if (root * root == sum) {
                count++;
            }
        }
    }
    return count;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 1) {
        return 1;
    }
    int[] sorted = A.clone();
    Arrays.sort(sorted);
    int count = 0;
    do {
        int sqrtSum = 0;
        for (int i = 0; i < n - 1; i++) {
            sqrtSum += sorted[i];
            if (!isPerfectSquare(sqrtSum)) {
                break;
            }
        }
        if (sqrtSum == sorted[n - 1] && isPerfectSquare(sqrtSum + sorted[n - 1])) {
            count++;
        }
    } while (Arrays.nextPermutation(A));
    return count;
}

