    return new int[0];
  }

  int rows = mat.length;
  int cols = mat[0].length;
  int[] result = new int[rows * cols];

  int i = 0, j = 0;
  for (int n = 0; n < rows * cols; n++) {
    result[n] = mat[i][j];
    i += 1;
    j += 1;
    if (i == rows) {
      i = 0;
      j += 1;
    }
    if (j == cols) {
      j = 0;
      i += 1;
    }
  }

  return result;
}

