public static int findSmallestInteger(int n) {
  if (n <= 0) {
    return -1;
  }

  int[] digits = new int[10];
  int digitCount = 0;
  while (n > 0) {
    digits[digitCount] = n % 10;
    n /= 10;
    digitCount++;
  }

  int result = 0;
  for (int i = 0; i < digitCount; i++) {
    result += digits[i] * (int)Math.pow(10, digitCount - i - 1);
  }

  return result;
}

