public static int findSmallestInteger(int n) {
    int largestInteger = Integer.MIN_VALUE;
    for (int i = n + 1; i <= Integer.MAX_VALUE; i++) {
        int currentInteger = i;
        int previousInteger = n;
        while (currentInteger > 0) {
            int currentDigit = currentInteger % 10;
            currentInteger /= 10;
            while (previousInteger > 0 && currentDigit > previousInteger % 10) {
                previousInteger /= 10;
            }
            if (currentDigit > previousInteger) {
                break;
            }
        }
        if (currentInteger > largestInteger) {
            largestInteger = currentInteger;
        }
    }
    return largestInteger == Integer.MIN_VALUE ? -1 : largestInteger;
}

public static int findSmallestInteger(int n) {
        // Convert the input integer to a string
        String s = String.valueOf(n);
        // Create an array of integers from the string
        int[] digits = new int[s.length()];
        for (int i = 0; i < s.length(); i++) {
            digits[i] = Character.getNumericValue(s.charAt(i));
        }
        // Sort the array of integers
        Arrays.sort(digits);
        // Convert the sorted array back to a string
        String sortedString = "";
        for (int i = 0; i < digits.length; i++) {
            sortedString += String.valueOf(digits[i]);
        }
        // Find the smallest possible integer greater than the input
        // by checking if any adjacent digits in the sorted string are swapped
        for (int i = digits.length - 2; i >= 0; i--) {
            if (digits[i] > digits[i + 1]) {
                // Swap the adjacent digits and return the new integer
                int temp = digits[i];
                digits[i] = digits[i + 1];
                digits[i + 1] = temp;
                break;
            }
        }
        int smallest = Integer.parseInt(sortedString);
        return smallest > n ? smallest : -1;
    }

