public static boolean isBoomerang(int[][] points) {
  // Check if the points array is valid and has exactly 3 points
  if (points == null || points.length != 3) {
    return false;
  }

  // Check if the points form a straight line
  double slope = (double)(points[0][1] - points[2][1]) / (double)(points[0][0] - points[2][0]);
  if (slope == (double)(points[1][1] - points[2][1]) / (double)(points[1][0] - points[2][0])) {
    return true;
  }

  return false;
}

public static boolean isBoomerang(int[][] points) {
        if (points.length != 3) return false;

        // find the equation of the line
        int x1 = points[0][0];
        int y1 = points[0][1];
        int x2 = points[1][0];
        int y2 = points[1][1];
        int x3 = points[2][0];
        int y3 = points[2][1];

        int a = (y2-y1)*(x3-x2) - (x2-x1)*(y3-y2);
        int b = (y3-y2)*(x1-x2) - (x3-x2)*(y1-y2);
        int c = (y1-y2)*(x2-x3) - (x1-x2)*(y2-y3);

        // if all three points are on the same line, it is not a boomerang
        if (a == 0 && b == 0 && c == 0) return false;

        // if the slope of the line is 0, it is a vertical line and not a boomerang
        if (a == 0 && b == 0) return false;

        // if the slope of the line is infinite, it is a horizontal line and not a boomerang
        if (b == 0 && c == 0) return false;

        return true;
    }

