        int next = Math.min(ugly[p2] * 2, Math.min(ugly[p3] * 3, ugly[p5] * 5));
        ugly[i] = next;
        if (next == ugly[p2] * 2) p2++;
        if (next == ugly[p3] * 3) p3++;
        if (next == ugly[p5] * 5) p5++;
    }
    return ugly[n];
}

