public static int calculateEnergy(String s) {
        // Initialize variables
        int maxLength = 0;
        int currentLength = 0;
        char previousChar = ' ';

        // Loop through the string
        for (int i = 0; i < s.length(); i++) {
            char currentChar = s.charAt(i);

            // Check if the current character is the same as the previous character
            if (currentChar == previousChar) {
                // If the current character matches the previous character, increment the current length
                currentLength++;
            } else {
                // If the current character does not match the previous character, check if the current length is greater than the max length
                if (currentLength > maxLength) {
                    maxLength = currentLength;
                }

                // Reset current length to 1
                currentLength = 1;
            }

            // Update the previous character
            previousChar = currentChar;
        }

        // Check if the final length is greater than the max length
        if (currentLength > maxLength) {
            maxLength = currentLength;
        }

        return maxLength;
    }

public static int calculateEnergy(String s) {
    int maxEnergy = 0;
    int currentEnergy = 0;
    char currentChar = s.charAt(0);
    for (int i = 1; i < s.length(); i++) {
        char nextChar = s.charAt(i);
        if (nextChar == currentChar) {
            currentEnergy++;
        } else {
            currentEnergy = 1;
            currentChar = nextChar;
        }
        maxEnergy = Math.max(maxEnergy, currentEnergy);
    }
    return maxEnergy;
}

