    for (int i = 1; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == currentChar) {
            currentCount++;
        } else {
            energy = Math.max(energy, currentCount);
            currentChar = c;
            currentCount = 1;
        }
    }
    return Math.max(energy, currentCount);
}

