public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        n -= root * root;
        count++;
    }
    return count;
}

public static int minPerfectSquareSum(int n) {
    int minNumber = Integer.MAX_VALUE;
    for (int i = 1; i * i <= n; i++) {
        int diff = n - i * i;
        int count = minPerfectSquareSum(diff);
        if (count < 0) {
            continue;
        }
        minNumber = Math.min(minNumber, count + 1);
    }
    return minNumber;
}

public static int minPerfectSquareSum(int n) {
    List<Integer> perfectSquares = new ArrayList<>();
    for (int i = 1; i <= Math.sqrt(n); i++) {
        perfectSquares.add(i * i);
    }
    int minCount = n;
    for (int i = 1; i <= n; i++) {
        int count = 0;
        for (int j : perfectSquares) {
            if (j <= i) {
                count++;
            } else {
                break;
            }
        }
        minCount = Math.min(minCount, count);
    }
    return minCount;
}

